package io.knowledgebrain.space;
import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;import io.knowledgebrain.contracts.space.groupprogresspolicy.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_SPACE_DATABASE_URL",matches=".+")
class GroupProgressPolicyIntegrationTest {
 GroupSpaceIntegrationTest f;GroupProgressPolicyStore store;UUID space,member;
 @BeforeEach void setup(){f=new GroupSpaceIntegrationTest();f.setup();space=f.store.provision(f.group,f.owner,f.trace).spaceId();store=new GroupProgressPolicyStore(f.source,Clock.systemUTC());member=f.ids.next();f.jdbc.update("INSERT INTO space_membership(space_id,principal_id,role,state,group_version) VALUES (?,?,'MEMBER','ACTIVE',1)",space,member);}
 GroupProgressPolicyStore.Policy change(long version,String mode){return store.change(f.group,f.owner,version,mode,f.trace);}
 void status(int code,org.junit.jupiter.api.function.Executable op){assertEquals(code,assertThrows(ResponseStatusException.class,op).getStatusCode().value());}
 @Test void defaultAndNoOpAllocateNothing(){assertNull(store.get(f.group,member).policyId());assertEquals(0,change(0,"DISABLED").version());assertTrue(store.history(f.group,f.owner,Long.MAX_VALUE,5).items().isEmpty());assertFalse(store.check(f.group,member,List.of()).enabled());}
 @Test void explicitEpochNeverReusesOldConsentAndWritesFullAudit()throws Exception{var first=change(0,"OWNER_SUMMARY");assertEquals(7,first.policyId().version());assertEquals(first,change(1,"OWNER_SUMMARY"));status(412,()->change(0,"OWNER_SUMMARY"));change(1,"DISABLED");var third=change(2,"OWNER_SUMMARY");assertEquals(first.policyId(),third.policyId());assertEquals(3,third.version());var history=store.history(f.group,f.owner,Long.MAX_VALUE,1);assertEquals(3L,history.nextBefore());assertEquals(2,store.history(f.group,f.owner,3,5).items().size());var bytes=f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=? ORDER BY occurred_at DESC LIMIT 1",byte[].class,third.policyId());var e=GroupProgressPolicyEnvelopeV1.parseFrom(bytes);assertEquals(f.trace,e.getTraceId());assertEquals("space-service",e.getProducer());assertEquals("OWNER",GroupProgressPolicySnapshotV1.parseFrom(e.getPayload()).getAudience());}
 @Test void onlyCurrentOwnerMutatesOrBatchesOtherMemberships(){status(403,()->store.change(f.group,member,0,"OWNER_SUMMARY",f.trace));status(403,()->store.history(f.group,member,Long.MAX_VALUE,5));status(403,()->store.check(f.group,member,List.of(f.owner)));status(404,()->store.get(f.group,f.ids.next()));status(400,()->store.check(f.group,f.owner,List.of(member,member)));}
 @Test void freshMembershipBatchExcludesRemovedAndCapturesRoleEpoch(){change(0,"OWNER_SUMMARY");assertEquals(1,store.check(f.group,f.owner,List.of(member)).activeMembers().getFirst().membershipVersion());f.jdbc.update("UPDATE space_membership SET role='VIEWER',group_version=2 WHERE space_id=? AND principal_id=?",space,member);assertEquals(2,store.check(f.group,f.owner,List.of(member)).activeMembers().getFirst().membershipVersion());f.jdbc.update("UPDATE space_membership SET state='RETIRED',group_version=3 WHERE space_id=? AND principal_id=?",space,member);assertTrue(store.check(f.group,f.owner,List.of(member)).activeMembers().isEmpty());status(404,()->store.get(f.group,member));}
 @Test void concurrentFirstChangesHaveOneWinner()throws Exception{try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var tasks=new ArrayList<Future<Boolean>>();for(int n=0;n<4;n++)tasks.add(pool.submit(()->{try{change(0,"OWNER_SUMMARY");return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));int won=0;for(var task:tasks)if(task.get(20,TimeUnit.SECONDS))won++;assertEquals(1,won);assertEquals(1,store.history(f.group,f.owner,Long.MAX_VALUE,5).items().size());}}
 @Test void policyOutboxFailureRollsBackCurrentAndAudit(){String name="policy_fail_"+f.group.toString().replace("-","");f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+" CHECK(aggregatetype<>'group-progress-policy' OR trace_id<>'"+f.trace+"') NOT VALID");try{assertThrows(RuntimeException.class,()->change(0,"OWNER_SUMMARY"));assertNull(store.get(f.group,f.owner).policyId());assertTrue(store.history(f.group,f.owner,Long.MAX_VALUE,5).items().isEmpty());}finally{f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}}
}
